import{_ as t,o,c as a,a2 as s}from"./chunks/framework.NwY0f7AV.js";const u=JSON.parse('{"title":"Use responsibly","description":"","frontmatter":{},"headers":[],"relativePath":"guide/responsible-use.md","filePath":"guide/responsible-use.md"}'),i={name:"guide/responsible-use.md"};function n(r,e,l,h,d,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="use-responsibly" tabindex="-1">Use responsibly <a class="header-anchor" href="#use-responsibly" aria-label="Permalink to &quot;Use responsibly&quot;">​</a></h1><p>wraith makes automation polite and natural-looking. It doesn&#39;t make it permitted. Before you point it at a site:</p><ul><li><strong>Read the site&#39;s terms of service.</strong> Many forbid automated access, or allow it only through an official API. If there&#39;s an API, use it.</li><li><strong>Keep the rate limit on</strong>, and lower it for small sites. Your scraper shouldn&#39;t be noticeable in the site&#39;s traffic.</li><li><strong>Turn on <code>respectRobotsTxt</code></strong> for sites you don&#39;t own, and set a <code>userAgent</code> that says who you are and how to reach you.</li><li><strong>Take only what you need</strong>, and cache it rather than fetching the same page again.</li><li><strong>Be careful with personal data.</strong> Scraping and storing information about people is regulated in many places (GDPR in the EU, DPDP in India, CCPA in California, and others).</li><li><strong>Don&#39;t bypass access controls.</strong> Logging in with your own account to automate your own tasks is one thing; getting into what you aren&#39;t allowed to see is another.</li></ul><h2 id="what-wraith-won-t-do" tabindex="-1">What wraith won&#39;t do <a class="header-anchor" href="#what-wraith-won-t-do" aria-label="Permalink to &quot;What wraith won&#39;t do&quot;">​</a></h2><p>wraith doesn&#39;t solve CAPTCHAs, send them to solving services, or ask AI models to solve them. A CAPTCHA is a site&#39;s explicit signal that it wants a person there, so wraith <a href="/WRAITH/guide/captchas">hands it to one</a>.</p><p>Human-like input, proxies and user agents exist so that automation of legitimate tasks is reliable and behaves the way the site&#39;s designers expect people to. They aren&#39;t tools for evading a site&#39;s decision to block automation, and the rate limit applies per site however many proxies or user agents you use. <a href="/WRAITH/guide/honeypots">Avoiding honeypots</a> keeps your scraper from tripping traps by accident; it doesn&#39;t make it welcome where it isn&#39;t.</p>',6)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
